class NZproxy:
  def __init__(self,matrix):
    self.matrix = matrix

  def __getitem__(self,s):
    return self.matrix.get_nz(False, s)

  def __setitem__(self,s,val):
    return self.matrix.set_nz(val, False, s)

  def __len__(self):
    return self.matrix.nnz()

  def __iter__(self):
    for i in range(len(self)):
      yield self[i]


class PrintableCommon(object):
    """


    ::

      PrintableCommon() -> 



    """

    thisown = property(lambda x: x.this.own(), lambda x, v: x.this.own(v), doc="The membership flag")
    __repr__ = _swig_repr

    def __str__(self): return self.str()
    def repr(self): return self.type_name() + '(' + self.str() + ')'
    # Value-copy semantics for all casadi types (DM/SX/MX/Sparsity/Function/
    # ...): copy via the copy constructor.  This base injects __copy__ /
    # __deepcopy__ into every subclass, replacing the old global-`object`
    # shadow hack.
    def __copy__(self): return self.__class__(self)
    def __deepcopy__(self, memo=None): return self.__class__(self)


    def __init__(self, *args):
        """


        ::

          PrintableCommon()
          PrintableCommon(PrintableCommon other)



        """
        _casadi.PrintableCommon_swiginit(self, _casadi.new_PrintableCommon(*args))
    __swig_destroy__ = _casadi.delete_PrintableCommon

# Register PrintableCommon in _casadi:
_casadi.PrintableCommon_swigregister(PrintableCommon)
