    def parameter(self,*args):
      import sys
      import os
      try:
          frame = sys._getframe(1)
      except:
          frame = {}
      meta = {} if frame is None else {"stacktrace": [{"file":os.path.abspath(frame.f_code.co_filename),"line":frame.f_lineno,"name":frame.f_code.co_name}]}
      ret = self._parameter(*args)
      if len(meta)>0:
          self.update_user_dict(ret, meta)
      return ret

    def variable(self,*args):
      import sys
      import os
      try:
          frame = sys._getframe(1)
      except:
          frame = {}
      meta = {} if frame is None else {"stacktrace": [{"file":os.path.abspath(frame.f_code.co_filename),"line":frame.f_lineno,"name":frame.f_code.co_name}]}
      ret = self._variable(*args)
      if len(meta)>0:
          self.update_user_dict(ret, meta)
      return ret

    def subject_to(self,*args):
      if len(args)==0:
        return self._subject_to()
      import sys
      import os
      stacktrace = []
      for i in range(1,10000):
        try:
          frame = sys._getframe(i)
          stacktrace.append({"file":os.path.abspath(frame.f_code.co_filename),"line":frame.f_lineno,"name":frame.f_code.co_name})
        except Exception as e:
          break
      args = list(args)
      if len(args)==3 and isinstance(args[2],dict):
        args[2] = dict(args[2])
        if "stacktrace" not in args[2]:
          args[2]["stacktrace"] = stacktrace
      elif len(args)==2 and isinstance(args[1],dict):
        args[1] = dict(args[1])
        if "stacktrace" not in args[1]:
          args[1]["stacktrace"] = stacktrace
      elif len(args)==1:
        args = [args[0], {"stacktrace": stacktrace}]
      elif len(args)==2:
        args = [args[0], args[1], {"stacktrace": stacktrace}]
      ret = self._subject_to(*args)
      return ret



    @staticmethod
    def _callback(self,fh=None):
      if fh is None:
        self.callback_class();
        return
      class OptiCallbackHelper(OptiCallback):
          def __init__(self, callback):
            OptiCallback.__init__(self)
            self.callback = callback

          def call(self, i):
            self.callback(i)

      self._fh = fh
      self._cb = OptiCallbackHelper(fh);
      self.callback_class(self._cb);


    def callback(self,fh=None):
      self._callback(self,fh)




    def __init__(self, *args):
        """


        ::

          Opti(str problem_type)
          Opti(Opti other)


        .......

        ::

          Opti(str problem_type)



        Create an empty Opti context.



        Parameters:
            problem_type: "nlp" (default): general nonlinear program, solved with an nlpsol plugin. "conic": quadratic program or SOCP, solved with a qpsol plugin; the objective must then be quadratic and the constraints linear or second-order cone. Any other string raises an error.

        ::

          >>> opti = Opti()
          >>> opti.nx, opti.np, opti.ng
          (0, 0, 0)
          >>> opti = Opti("conic")
          >>> x = opti.variable(2)
          >>> opti.minimize(sumsqr(x-1))
          >>> opti.subject_to(x[0]+x[1] <= 1)
          >>> opti.solver("qrqp", {"print_time": False, "print_iter": False,
          ...                      "print_header": False, "print_info": False})
          >>> opti.solve().value(x)
          array([0.5, 0.5])
          >>> try:
          ...   Opti("lp")
          ... except Exception as e:
          ...   print(str(e).splitlines()[-1])
          Specified problem type 'lp'unknown. Choose 'nlp' (default) or 'conic'.


        Extra doc: https://github.com/casadi/casadi/wiki/L_17

        Doc source:
        https://github.com/casadi/casadi/blob/main/casadi/core/optistack.hpp#L308
        Implementation:
        https://github.com/casadi/casadi/blob/main/casadi/core/optistack.cpp#L47-L49


        .............


        .......

        ::

          Opti(Opti other)



        .............



        """
        _casadi.Opti_swiginit(self, _casadi.new_Opti(*args))
    __swig_destroy__ = _casadi.delete_Opti

