class OptiSol(PrintableCommon):
    """
      Snapshot of an Opti problem and its solution.

    ::



    Returned by Opti::solve and Opti::solve_limited. It is a deep copy made at
    that moment: later set_value/set_initial/subject_to calls on the Opti do not
    change what value() returns, so several OptiSol objects can be kept and
    compared. The API is guaranteed to be stable.

    ::

      >>> opti = Opti()
      >>> x = opti.variable()
      >>> p = opti.parameter()
      >>> opti.minimize((x-p)**2)
      >>> opti.solver("ipopt", {"print_time": False}, {"print_level": 0, "sb": "yes"})
      >>> opti.set_value(p, 1)
      >>> sol1 = opti.solve()
      >>> opti.set_value(p, 2)
      >>> sol2 = opti.solve()
      >>> sol1.value(x), sol2.value(x)
      (1.0, 2.0)


    Authors: Joris Gillis, Erik Lambrechts

    Extra doc: https://github.com/casadi/casadi/wiki/L_1v




    """

    thisown = property(lambda x: x.this.own(), lambda x, v: x.this.own(v), doc="The membership flag")
    __repr__ = _swig_repr

    def type_name(self, *args):
        """


        ::

          type_name(self) -> str



        """
        return _casadi.OptiSol_type_name(self, *args)

    def disp(self, *args):
        """


        ::

          disp(self, bool more)



        """
        return _casadi.OptiSol_disp(self, *args)

    def str(self, *args):
        """


        ::

          str(self, bool more) -> str



        """
        return _casadi.OptiSol_str(self, *args)

    def value(self, *args):
        """


        ::

          value(self, DM x, [MX] values) -> double
          value(self, SX x, [MX] values) -> double
          value(self, MX x, [MX] values) -> double


        .......

        ::

          value(self, DM x, [MX] values)
          value(self, SX x, [MX] values)



        .............


        .......

        ::

          value(self, MX x, [MX] values)



        Evaluate an expression at the solution.

        Same as Opti::value on the snapshot: variables take their optimal values,
        parameters the values used for the solve, dual variables the multipliers.
        ``values`` overrules individual symbols for this evaluation only, e.g.
        opti.initial() to evaluate at the initial guess.



        Parameters:
            x: Expression (MX) in the symbols of the Opti; a DM is returned as is
            values: Optional list of assignments var==value

        A scalar becomes a float, a dense matrix a numpy array and a sparse matrix a
        scipy sparse matrix.



        ::

          >>> opti = Opti()
          >>> x = opti.variable()
          >>> y = opti.variable()
          >>> opti.minimize((y-x**2)**2)
          >>> opti.subject_to(x**2+y**2==1)
          >>> opti.subject_to(x+y>=1)
          >>> opti.solver("ipopt", {"print_time": False}, {"print_level": 0, "sb": "yes"})
          >>> sol = opti.solve()
          >>> sol.value(x), sol.value(vertcat(x, y)).shape
          (0.7862, (2,))
          >>> sol.value(opti.f, [y==2])
          1.9098
          >>> sol.value(x**2+y, opti.initial())
          0.0
          >>> sol.value(jacobian(opti.g, opti.x)).shape
          (2, 2)


        Extra doc: https://github.com/casadi/casadi/wiki/L_2nd

        Doc source:
        https://github.com/casadi/casadi/blob/main/casadi/core/optistack.hpp#L3649
        Implementation:
        https://github.com/casadi/casadi/blob/main/casadi/core/optistack.cpp#L872-L874


        .............



        """
        return _casadi.OptiSol_value(self, *args)

    def value_variables(self, *args):
        """
          Get assignment expressions for the optimal solution.

        ::

          value_variables(self) -> [MX]


        value_variables() gives value==var for every variable, value_parameters()
        value==par for every parameter. Pass them to Opti::set_initial /
        Opti::set_value to warm start the next solve.

        ::

          >>> opti = Opti()
          >>> x = opti.variable()
          >>> p = opti.parameter()
          >>> opti.minimize((x-p)**2)
          >>> opti.set_value(p, 2)
          >>> opti.solver("ipopt", {"print_time": False}, {"print_level": 0, "sb": "yes"})
          >>> sol = opti.solve()
          >>> print(sol.value_variables(), sol.value_parameters())
          [MX((2==opti..._x_1))] [MX((2==opti..._p_1))]
          >>> opti.set_initial(sol.value_variables())
          >>> opti.solve().stats()["iter_count"]
          0


        Extra doc: https://github.com/casadi/casadi/wiki/L_2ne

        Doc source:
        https://github.com/casadi/casadi/blob/main/casadi/core/optistack.hpp#L3711
        Implementation:
        https://github.com/casadi/casadi/blob/main/casadi/core/optistack.cpp#L882-L884



        """
        return _casadi.OptiSol_value_variables(self, *args)

    def value_parameters(self, *args):
        """


        ::

          value_parameters(self) -> [MX]



        """
        return _casadi.OptiSol_value_parameters(self, *args)

    def stats(self, *args):
        """
          Get the solver statistics of this solve.

        ::

          stats(self) -> dict


        The dict returned by the nlpsol/qpsol plugin, passed as-is ("success",
        "return_status", "iter_count", ...). No stability is guaranteed for the
        entries.

        ::

          >>> opti = Opti()
          >>> x = opti.variable()
          >>> opti.minimize((x-1)**2)
          >>> opti.solver("ipopt", {"print_time": False}, {"print_level": 0, "sb": "yes"})
          >>> sol = opti.solve()
          >>> sol.stats()["success"], sol.stats()["return_status"]
          (True, 'Solve_Succeeded')


        Extra doc: https://github.com/casadi/casadi/wiki/L_1w

        Doc source:
        https://github.com/casadi/casadi/blob/main/casadi/core/optistack.hpp#L3755
        Implementation:
        https://github.com/casadi/casadi/blob/main/casadi/core/optistack.cpp#L890-L892



        """
        return _casadi.OptiSol_stats(self, *args)

    def _opti(self, *args):
        """
          Get the Opti copy this solution belongs to.

        ::

          _opti(self) -> Opti


        An Opti holding the state at the time of the solve; opti.debug on it gives
        the OptiAdvanced accessors. In Python this is a read-only property.

        ::

          >>> opti = Opti()
          >>> x = opti.variable()
          >>> opti.minimize((x-1)**2)
          >>> opti.solver("ipopt", {"print_time": False}, {"print_level": 0, "sb": "yes"})
          >>> sol = opti.solve()
          >>> sol.opti.return_status(), sol.opti.debug.value(x)
          ('Solve_Succeeded', 1.0)


        Extra doc: https://github.com/casadi/casadi/wiki/L_2nf

        Doc source:
        https://github.com/casadi/casadi/blob/main/casadi/core/optistack.hpp#L3799
        Implementation:
        https://github.com/casadi/casadi/blob/main/casadi/core/optistack.hpp#L3799-L3799



        """
        return _casadi.OptiSol__opti(self, *args)

    @property
    def opti(self):
      return self._opti()


    def __init__(self, *args):
        """


        ::

          OptiSol(OptiSol other)



        """
        _casadi.OptiSol_swiginit(self, _casadi.new_OptiSol(*args))
    __swig_destroy__ = _casadi.delete_OptiSol

# Register OptiSol in _casadi:
_casadi.OptiSol_swigregister(OptiSol)
